from author_tools import *
N(bank,6,201,C,'Делимость и простые числа','15',[
('6-divisible-three-digit-sum','Найдите сумму цифр числа 7341. Используйте её, чтобы проверить делимость на 3; ответом является сама сумма цифр.',15,'7 + 3 + 4 + 1 = 15. Сумма делится на 3, значит исходное число тоже делится на 3.','sum(map(int,str(7341)))','b'),
('6-prime-one-exclusion','Сколько простых чисел среди 1, 2, 9, 11, 15, 17?',3,'Простые — 2, 11, 17. Число 1 не простое: у него только один натуральный делитель, а требуется два.','sum(isprime(n) for n in [1,2,9,11,15,17])','b',{'tricky':True}),
('6-digit-divisibility-nine','Замените □ одной цифрой так, чтобы число 5□3 делилось на 9. Найдите эту цифру.',1,'Сумма цифр 8 + □ должна делиться на 9. В возможном диапазоне 8–17 подходит 9, поэтому цифра 1.','[d for d in range(10) if (503+10*d)%9==0][0]','m'),
('6-divisibility-four-tail','Сколько чисел вида 73□ делятся на 4, если □ — одна цифра?',2,'Достаточно проверить последние две цифры. Между 30 и 39 на 4 делятся 32 и 36. Значит подходят два числа.','len([d for d in range(10) if (730+d)%4==0])','m'),
('6-two-divisibility-digits','В числе 4□5 последняя цифра фиксирована. Число делится и на 3, и на 5. Найдите сумму всех возможных цифр на месте □.',18,'На 5 число уже делится. Для делимости на 3 сумма 9 + □ должна делиться на 3. Подходят 0, 3, 6, 9, их сумма 18.','sum(d for d in range(10) if (405+10*d)%3==0 and (405+10*d)%5==0)','h'),
('6-prime-square-divisors','Натуральное число имеет ровно три натуральных делителя и меньше 20. Найдите сумму всех таких чисел.',13,'Ровно три делителя имеют квадраты простых чисел. Меньше 20 это 4 и 9. Их сумма 13. Для 16 делителей пять, оно не подходит.','sum(n for n in range(1,20) if sum(n%d==0 for d in range(1,n+1))==3)','s'),
('6-product-prime-factor','Произведение двух натуральных чисел равно 13. Найдите сумму этих чисел.',14,'13 — простое число, поэтому натуральные множители только 1 и 13. Их сумма 14 независимо от порядка.','sum(next((a,13//a) for a in range(1,14) if 13%a==0))','m'),
('6-odd-product-parity','Сумма трёх последовательных натуральных чисел нечётна. Какой остаток даёт их произведение при делении на 2?',0,'В любых трёх последовательных числах есть чётное. Поэтому произведение чётно независимо от дополнительного условия о сумме; остаток 0.','(1*2*3)%2','h',{'tricky':True}),
('6-divisor-list-completeness','У числа 36 выписали делители 1, 2, 3, 4, 6, 9, 12 и 36. Какой натуральный делитель пропущен?',18,'Делители удобно искать парами с произведением 36: 1 и 36, 2 и 18, 3 и 12, 4 и 9, 6 и 6. Не выписано 18.','next(d for d in range(1,37) if 36%d==0 and d not in [1,2,3,4,6,9,12,36])','m'),
('6-primes-consecutive-product','Два простых числа отличаются на 1. Найдите их произведение.',6,'Из двух соседних чисел одно чётное. Единственное чётное простое — 2, его соседнее простое — 3. Произведение 6.','2*3','s',{'tricky':True})])
N(bank,6,202,C,'НОД и НОК: свойства и обратные задачи','15',[
('6-gcd-divides-other','Одно из чисел 15 и 60 делится на другое. Найдите их НОД.',15,'Каждый общий делитель делит 15, а само 15 делит оба числа. Поэтому НОД равен 15.','gcd(15,60)','b'),
('6-lcm-nested-period','Два сигнала повторяются через 6 и 18 секунд. Сейчас они совпали. Сколько раз за следующие 54 секунды, включая момент 54, они снова совпадут?',3,'Совпадения каждые 18 секунд: через 18, 36 и 54. Начальный момент не входит в «следующие», поэтому три раза.','len([t for t in range(1,55) if t%6==0 and t%18==0])','m'),
('6-gcd-consecutive','Найдите НОД чисел 1234 и 1235.',1,'Общий делитель делит и их разность 1. Поэтому наибольший общий делитель равен 1.','gcd(1234,1235)','m'),
('6-gcd-linear-combination','Найдите НОД чисел 84 и 198, пользуясь тем, что 198 − 2 · 84 = 30.',6,'НОД не меняется при вычитании кратного: НОД(84, 198) = НОД(84, 30) = НОД(30, 24) = НОД(24, 6) = 6.','gcd(84,198)','h'),
('6-lcm-coprime-product','Числа 8 и n взаимно просты, их НОК равен 56. Найдите n.',7,'Для взаимно простых чисел НОК равен произведению. Из 8n = 56 получаем n = 7, оно действительно взаимно просто с 8.','56/8','h'),
('6-cut-rectangle-square','Прямоугольный лист 42 × 30 см разрезают на одинаковые квадраты максимально возможной целой стороны без остатка. Сколько квадратов получится?',35,'Максимальная сторона квадрата НОД(42, 30) = 6 см. По сторонам помещаются 7 и 5 квадратов, всего 35.','42*30/gcd(42,30)**2','s'),
('6-common-remainder-infer','При делении некоторого числа на 6 и на 8 остаток каждый раз равен 5. Найдите наименьшее такое число, большее 5.',29,'После вычитания 5 число делится и на 6, и на 8. Наименьшее положительное общее кратное 24. Искомое число 24 + 5 = 29.','min(n for n in range(6,100) if n%6==5 and n%8==5)','h'),
('6-gcd-greater-not-possible','У двух натуральных чисел НОД равен 12. Может ли одно из чисел быть 30? Введите 1, если может, и 0, если нет.',0,'НОД должен делить каждое число. 30 не делится на 12, поэтому такая пара невозможна.','int(30%12==0)','m',{'tricky':True}),
('6-gcd-lcm-existence','НОД двух натуральных чисел равен 6, а НОК — 20. Сколько пар таких чисел существует?',0,'НОД всегда является делителем НОК. Число 20 не делится на 6, значит такие числа не существуют. Произведение 120 само по себе существования не гарантирует.','len([(a,b) for a in range(1,21) for b in range(a,21) if gcd(a,b)==6 and lcm(a,b)==20])','s',{'tricky':True}),
('6-reduced-pair-reconstruct','НОД двух натуральных чисел равен 5. После деления обоих на НОД получились 4 и 7. Найдите НОК исходных чисел.',140,'Исходные числа 20 и 35. После удаления общего множителя 5 остаются взаимно простые 4 и 7, поэтому НОК = 5 · 4 · 7 = 140.','lcm(5*4,5*7)','m')])
N(bank,6,203,C,'Целые числа и координатная прямая','16',[
('6-opposite-number','Найдите число, противоположное числу −13.',13,'Противоположные числа в сумме дают ноль. Для −13 это 13.','-(-13)','b'),
('6-number-line-count','Сколько целых чисел лежит строго между −5 и 4?',8,'Это −4, −3, −2, −1, 0, 1, 2, 3. Всего 8, включая ноль.','len(list(range(-4,4)))','b'),
('6-additive-inverse-unknown','Сумма целого числа n и противоположного ему числа равна 0. Чему равна сумма n + 5 и числа, противоположного n?',5,'n и −n взаимно уничтожаются. Остаётся 5 при любом n.','(17+5)-17','h'),
('6-elevator-floors-no-zero','Лифт поднялся с этажа −2 на этаж 5. В здании есть этаж 0, соседние номера отличаются на 1. Сколько промежутков между этажами он проехал?',7,'При наличии нулевого этажа разность номеров равна числу промежутков: 5 − (−2) = 7. Наличие этажа 0 указано явно.','5-(-2)','m'),
('6-temperature-range-days','Минимальная температура за сутки −9 °C, максимальная 4 °C. Найдите суточный размах в градусах.',13,'Размах — разность максимума и минимума: 4 − (−9) = 13 градусов.','4-(-9)','m'),
('6-negative-coordinate-midpoint','Точка находится посередине между −11 и 3 на координатной прямой. Найдите её координату.',-4,'Расстояние между концами 14, половина 7. От −11 вправо на 7 получаем −4.','(-11+3)/2','h'),
('6-signed-balance-debt','Баланс счёта равен −450 рублей. Внесли 700 рублей, затем потратили 320. Найдите конечный баланс в рублях.',-70,'После внесения баланс 250 рублей. После расхода 320 рублей он равен −70.','-450+700-320','m'),
('6-order-negative-fractions','Найдите наибольшее число среди −1/2, −1/3 и −1/4.',(-.25,'−1/4'),'У отрицательных чисел больше то, которое ближе к нулю. Из данных это −1/4.','max(-F(1,2),-F(1,3),-F(1,4))','h'),
('6-interval-symmetric-count','Сумма всех целых чисел от −20 до 18 включительно равна чему?',-39,'Числа от −18 до 18 попарно уничтожаются. Остаются −20 и −19, сумма −39.','sum(range(-20,19))','s',{'tricky':True}),
('6-unknown-direction-distance','На прямой точка A имеет координату −2. Точка B находится на расстоянии 5 от A. Укажите все возможные координаты B.',([-7,3],'−7; 3'),'От A можно отойти на 5 как вправо, так и влево: −2 + 5 = 3 и −2 − 5 = −7. Направление не задано, нужны оба ответа.','[-2-5,-2+5]','s',{'tricky':True})])
N(bank,6,204,C,'Рациональные числа: знаки и порядок действий','16',[
('6-negative-product-sign-count','Вычислите (−2) · (−3) · (−4).',-24,'Первые два отрицательных множителя дают +6, умножение на третий даёт −24. Нечётное число отрицательных множителей делает результат отрицательным.','(-2)*(-3)*(-4)','b'),
('6-subtract-negative-fraction','Вычислите −3/4 − (−1/2).',(-.25,'−1/4'),'Вычитание отрицательного числа заменяем сложением: −3/4 + 2/4 = −1/4.','-F(3,4)-(-F(1,2))','m'),
('6-negative-division-order','Вычислите 24 : (−3) : 2.',-4,'Деления выполняются слева направо: 24 : (−3) = −8, затем −8 : 2 = −4.','24/(-3)/2','b'),
('6-unary-minus-square','Вычислите −5² + (−5)².',0,'В первом слагаемом сначала степень: −25. Во втором отрицательное основание в скобках даёт +25. Сумма 0.','-(5**2)+(-5)**2','h',{'tricky':True}),
('6-negative-fraction-reciprocal','Найдите число, обратное числу −2/3.',(-1.5,'−3/2'),'Обратное число при умножении на исходное даёт 1. Для −2/3 это −3/2; знак остаётся отрицательным.','1/(-F(2,3))','m'),
('6-zero-reciprocal','Сколько чисел, обратных нулю, существует?',0,'Произведение нуля на любое число равно нулю и не может равняться 1. Поэтому обратного нулю числа нет.','0','h',{'tricky':True}),
('6-product-sign-unknown','Произведение трёх ненулевых чисел отрицательно. Два из них отрицательны. Каков знак третьего? Введите −1 для отрицательного и 1 для положительного.',-1,'Два отрицательных числа дают положительное произведение. Чтобы итог был отрицательным, третье число должно быть отрицательным.','-1','m'),
('6-factor-zero-in-long-product','Найдите произведение всех целых чисел от −3 до 4 включительно.',0,'Среди множителей есть 0. Поэтому всё произведение равно нулю, остальные множители вычислять не нужно.','prod(range(-3,5))','m',{'tricky':True}),
('6-negative-odd-even-sum','Вычислите (−1)¹ + (−1)² + … + (−1)¹⁰¹.',-1,'Каждая пара соседних слагаемых −1 и +1 даёт ноль. После 50 пар остаётся (−1)¹⁰¹ = −1.','sum((-1)**k for k in range(1,102))','s',{'tricky':True}),
('6-expression-sign-with-constraint','Известно a < 0. Найдите значение a/|a| + |a|/a.',-2,'При a < 0 модуль равен −a. Каждое из двух частных равно −1, сумма −2. Нулевое a исключено условием.','(-3)/abs(-3)+abs(-3)/(-3)','s')])
N(bank,6,205,C,'Модуль как расстояние','16',[
('6-modulus-evaluate-expression','Вычислите |2 − 9|.',7,'Внутри модуля получается −7. Его расстояние до нуля равно 7.','abs(2-9)','b'),
('6-modulus-equation-shift','Решите |x − 3| = 2. Укажите все корни.',([1,5],'1; 5'),'Расстояние от x до 3 равно 2. Значит x = 3 − 2 = 1 или x = 3 + 2 = 5.','[3-2,3+2]','m'),
('6-modulus-no-negative-distance','Сколько решений имеет уравнение |x + 4| = −2?',0,'Модуль неотрицателен, а справа отрицательное число. Равенство невозможно.','0','b',{'tricky':True}),
('6-absolute-sum-vanish','Найдите x, если |x − 7| + |x − 7| = 0.',7,'Оба слагаемых неотрицательны. Чтобы сумма была нулём, каждый модуль должен быть нулём, поэтому x = 7.','7','h'),
('6-distances-to-two-points','Точка x находится между −2 и 6 включительно. Найдите |x + 2| + |x − 6|.',8,'Это сумма расстояний от x до концов отрезка. Внутри отрезка сумма равна его длине 6 − (−2) = 8, независимо от положения x.','6-(-2)','h'),
('6-absolute-equal-distances','Решите |x − 1| = |x − 9|.',5,'Точка, равноудалённая от 1 и 9 на прямой, — середина отрезка. Её координата (1 + 9)/2 = 5.','(1+9)/2','m'),
('6-absolute-count-annulus','Сколько целых x удовлетворяют 2 < |x| ≤ 5?',6,'Положительные: 3, 4, 5; отрицательные: −3, −4, −5. Всего шесть. Числа ±2 исключены строгим знаком.','len([x for x in range(-10,11) if 2<abs(x)<=5])','h'),
('6-minimum-sum-distances-integer','Найдите наименьшее значение |x − 2| + |x − 8| при целых x.',6,'Сумма расстояний до двух точек не меньше расстояния между ними, то есть 6. Любое целое x от 2 до 8 достигает этого значения.','min(abs(x-2)+abs(x-8) for x in range(-20,21))','s'),
('6-absolute-vs-sum','Для a = −5 и b = 2 найдите |a| + |b| − |a + b|.',4,'Первые два модуля дают 5 + 2 = 7. Модуль суммы |−3| = 3. Разность 4: модуль суммы не всегда равен сумме модулей.','abs(-5)+abs(2)-abs(-5+2)','m',{'tricky':True}),
('6-double-absolute','Сколько целых решений имеет ||x| − 3| = 1?',4,'Внешний модуль даёт |x| − 3 = ±1, значит |x| = 2 или 4. Корни −4, −2, 2, 4; их четыре.','len([x for x in range(-10,11) if abs(abs(x)-3)==1])','s',{'tricky':True})])
